private void enlarge(final int size){
    if (size <= 0) {
        return;
    }
    try {
        if (bytes == null) {
            bytes = new byte[Math.max(1, size)];
            return;
        }
        int newSize = this.size + size;
        if (newSize < 0) { // overflow
            newSize = Integer.MAX_VALUE;
        }
        if (newSize > bytes.length) {
            int newCapacity = Math.max(bytes.length * 2, newSize);
            byte[] newBytes = new byte[newCapacity];
            System.arraycopy(bytes, 0, newBytes, 0, this.size);
            bytes = newBytes;
        }
    } catch (OutOfMemoryError e) {
        throw new RuntimeException("Failed to enlarge byte vector", e);
    }
}

