private boolean unlink(ListNodeImpl<E> node){
    if (node == null) {
        return false;
    }
    // Detach the node from its neighbors
    if (node.prev != null) {
        node.prev.next = node.next;
    } else {
        // node was the head
        head = node.next;
    }
    if (node.next != null) {
        node.next.prev = node.prev;
    } else {
        // node was the tail
        tail = node.prev;
    }
    // Clear the node's pointers
    node.prev = null;
    node.next = null;
    // Update size if the list tracks it
    if (size > 0) {
        size--;
    }
    return true;
}

