private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    if (bounds == null || bounds.isEmpty()) {
        return new Pair<>(Collections.emptyList(), 0L);
    }
    int n = bounds.size();
    long total = 0;
    int[] suffix = new int[n];
    for (int i = n - 1; i >= 0; i--) {
        total += bounds.get(i);
        suffix[i] = (int) total;
    }
    List<Integer> suffixList = new ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        suffixList.add(suffix[i]);
    }
